import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { IonRouterOutlet, NavController } from '@ionic/angular';
import { RegexRouteName } from '@rsApp/core/enum';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { debounceTime, fromEvent, Subject, takeUntil } from 'rxjs';
import { Location } from '@angular/common';

@Component({
  selector: 'app-shopping-list-detail',
  templateUrl: './shopping-list-detail.component.html',
  styleUrls: ['./shopping-list-detail.component.scss'],
})
export class ShoppingListDetailComponent implements OnInit, OnDestroy {
  magShoppingListDetail = '';
  listId: string;

  private destroy$ = new Subject<boolean>();
  private previousPath = '';

  constructor(
    public dxpComponentService: DxpComponentService,
    public router: Router,
    private activeRoute: ActivatedRoute,
    private navCtrl: NavController,
    public routerOutlet: IonRouterOutlet,
    public location: Location
  ) {
    this.previousPath = this.router.getCurrentNavigation()?.previousNavigation?.finalUrl.toString();
  }

  async ngOnInit() {
    await this.dxpComponentService.onConnected();

    this.listId = this.activeRoute.snapshot.paramMap.get('id')!;
    this.magShoppingListDetail = `<mag-shopping-list-detail-page shopping-list-id='${this.listId}'></mag-shopping-list-detail-page>`;

    fromEvent(window, 'backToList')
      .pipe(takeUntil(this.destroy$), debounceTime(300))
      .subscribe(async () => {
        if (!this.routerOutlet.canGoBack()) {
          this.router.navigateByUrl('tabs/home', { replaceUrl: true });
          return;
        }

        if (this.previousPath) {
          this.navCtrl.back();
        } else {
          this.navCtrl.setDirection('back');
          this.router.navigate(['/tabs/home'], { replaceUrl: true });
        }
      });
  }

  ngOnDestroy() {
    this.magShoppingListDetail = '';
    this.destroy$.next(true);
  }

  handleNavigation() {
    // if (!this.routerOutlet.canGoBack()) {
    //   this.router.navigateByUrl('tabs/home', { replaceUrl: true });
    //   return;
    // }
    if (RegexRouteName.LOGIN.test(this.previousPath)) {
      this.navCtrl.setDirection('back');
      this.router.navigate(['/home'], { replaceUrl: true });
    } else {
      this.location.back();
    }
  }
}
