import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { RegexRouteName } from '@rsApp/core/enum';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'app-shopping-lists',
  templateUrl: './shopping-lists.component.html',
  styleUrls: ['./shopping-lists.component.scss'],
})
export class ShoppingListsComponent implements OnInit, OnDestroy {
  magShoppingList = '';
  innerIconShoppingList = '';
  private previousPath = '';
  public destroy$ = new Subject<boolean>();
  constructor(
    public dxpComponentService: DxpComponentService,
    public router: Router,
    private navCtrl: NavController,
    public events: NgxPubSubService,
    public route: ActivatedRoute
  ) {
    this.previousPath = this.router.getCurrentNavigation().previousNavigation?.finalUrl.toString();
  }

  async ngOnInit() {
    this.router.events.pipe(takeUntil(this.destroy$)).subscribe(async (event) => {
      if (event instanceof NavigationEnd) {
        const urlPath = event.url.split('?')[0]; // strip query params
        if (urlPath === '/shopping-list') {
          await this.dxpComponentService.onConnected();
          this.magShoppingList = `<mag-shopping-list-page></mag-shopping-list-page>`;
        } else {
          this.magShoppingList = ``;
        }
      }
    });
  }

  ngOnDestroy() {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  handleNavigation() {
    if (RegexRouteName.LOGIN.test(this.previousPath)) {
      this.navCtrl.setDirection('back');
      this.router.navigate(['/home'], { replaceUrl: true });
    } else {
      this.navCtrl.back();
    }
  }
}
